"""Self-contained Ascend Triton ``scatter_add`` (out-of-place and in-place).

Semantics (``torch.scatter_add``)::

    out = inp.clone()
    out[index[i_0, ..., i_d, ...]] += src[i_0, ..., i_d, ...]   (along ``dim``)

``src`` may be larger than ``index``; only the ``index.shape`` region is read.

This is the Ascend backend implementation.  Compared with the generic
``flag_gems.ops.scatter_add`` it specializes the by-far most common layout --
a 2-D, contiguous, last-axis scatter -- and no longer requires
``inp.shape == index.shape``: the benchmark (and real models) scatter a source
with *twice* the destination width, which the generic fast path rejects and
therefore handles with per-element atomics.

Three last-axis strategies are used, all accumulating in **fp32** (the device
reference rounds once on store; a per-add low-precision fold doesn't match):

* **destination-owned** (``out_cols <= 256``): one program owns a destination
  block of a row and folds every source element into it with an affine compare,
  so each output element is written exactly once, contiguously, without atomics.
* **sorted-segment** (``max(out_cols, src_cols) <= 4096``): sort
  ``target*B + lane`` keys per row, which groups each destination's
  contributions into one contiguous, lane-ordered run; a segmented prefix sum
  then yields the dense output without scattering.
* **atomic** (wide rows): ``tl.atomic_add`` into an fp32 buffer (or directly
  into the output for fp32) -- the only path where the destination side cannot
  be owned.

Everything else falls through to a strided N-d kernel that handles any ``dim``,
non-contiguous inputs and rank > 2.
"""

import logging

import torch
import triton
import triton.language as tl
from triton.language.extra.cann import extension as _al

_MAXR = 8
_COPY_BLOCK = 8192
_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)
_DENSE_MAX_COLS = 1024  # destination-owned path upper bound
_DENSE_MAX_SRC = 4096  # ... and its source-width bound
_SORT_MAX_B = 1024  # wider sorts exceed the 196 KB UB budget
_DENSE_CHUNK = 32
_ATOMIC_BLOCK = 1024
_INT32_MAX = 2**31 - 1

_D_ARGS = [f"d{i}" for i in range(_MAXR)]
_SS_ARGS = [f"ss{i}" for i in range(_MAXR)]
_IS_ARGS = [f"is{i}" for i in range(_MAXR)]
_OS_ARGS = [f"os{i}" for i in range(_MAXR)]

logger = logging.getLogger(__name__)


