# destination-owned last-axis kernel (no atomic, single launch)
# --------------------------------------------------------------------------- #
@triton.jit
def _scatter_add_owner_kernel(
    inp_ptr,
    idx_ptr,
    src_ptr,
    out_ptr,
    rows,
    col_blocks,
    out_cols: tl.constexpr,
    src_cols: tl.constexpr,
    src_row_stride: tl.constexpr,
    BLOCK: tl.constexpr,
    CHUNK: tl.constexpr,
    EVEN: tl.constexpr,
):
    pid = tl.program_id(0)
    npid = tl.num_programs(0)
    total = rows * col_blocks
    for t in range(pid, total, npid):
        row = t // col_blocks
        col_blk = t - row * col_blocks
        dst = col_blk * BLOCK + tl.arange(0, BLOCK)
        idx_base = row * src_cols
        src_base = row * src_row_stride
        out_base = row * out_cols
        acc = tl.zeros([BLOCK], dtype=tl.float32)
        if EVEN:
            # ``src_cols`` is a multiple of CHUNK and ``out_cols`` a multiple of
            # BLOCK: every lane is live, so both the loop and the final
            # load/store run unmasked with a compile-time trip count.
            for s0 in range(0, src_cols, CHUNK):
                so = s0 + tl.arange(0, CHUNK)
                idx = tl.load(idx_ptr + idx_base + so).to(tl.int32)
                val = tl.load(src_ptr + src_base + so).to(tl.float32)
                acc += tl.sum(
                    tl.where(idx[:, None] == dst[None, :], val[:, None], 0.0), axis=0
                )
            cur = tl.load(inp_ptr + out_base + dst).to(tl.float32)
            tl.store(out_ptr + out_base + dst, (cur + acc).to(out_ptr.dtype.element_ty))
        else:
            dmask = dst < out_cols
            for s0 in range(0, src_cols, CHUNK):
                so = s0 + tl.arange(0, CHUNK)
                smask = so < src_cols
                # ``other=-1`` keeps masked lanes from matching a non-negative
                # destination, so the compare needs no extra mask term.
                idx = tl.load(idx_ptr + idx_base + so, mask=smask, other=-1).to(
                    tl.int32
                )
                val = tl.load(src_ptr + src_base + so, mask=smask, other=0).to(
                    tl.float32
                )
                acc += tl.sum(
                    tl.where(idx[:, None] == dst[None, :], val[:, None], 0.0), axis=0
                )
            cur = tl.load(inp_ptr + out_base + dst, mask=dmask, other=0).to(tl.float32)
            tl.store(
                out_ptr + out_base + dst,
                (cur + acc).to(out_ptr.dtype.element_ty),
                mask=dmask,
            )


# --------------------------------------------------------------------------- #
# sorted-segment last-axis path (wide rows)
# --------------------------------------------------------------------------- #
@triton.jit
def _scatter_add_sort_key_kernel(
    src_ptr,
    idx_ptr,
    keys_ptr,
    prefix_ptr,
    rows,
    out_cols: tl.constexpr,
    src_cols: tl.constexpr,
    src_row_stride: tl.constexpr,
    B: tl.constexpr,
    LOG: tl.constexpr,
):
    """Per row: sort ``target*B + lane`` keys, gather values into sorted order,
    store the sorted keys (fp32) and their segmented inclusive sums."""
    pid = tl.program_id(0)
    npid = tl.num_programs(0)
    lane = tl.arange(0, B)
    live = lane < src_cols
    for row in range(pid, rows, npid):
        idx_base = row * src_cols
        src_base = row * src_row_stride
        t = tl.load(idx_ptr + idx_base + lane, mask=live, other=B).to(tl.int32)
        key = _al.sort((t * B + lane).to(tl.float32), dim=-1)
        keyi = key.to(tl.int32)
        src_lane = tl.minimum(keyi & (B - 1), src_cols - 1)
        values = tl.load(src_ptr + src_base + lane, mask=live, other=0.0).to(tl.float32)
        sv = tl.gather(values, src_lane, axis=0)
        # Valid keys sort first (masked lanes use target B, the largest target);
        # zero their values so junk segments add nothing.
        sv = tl.where(lane < src_cols, sv, 0.0)
        tl.store(keys_ptr + row * B + lane, key)
        targets = keyi >> LOG
        segment_sums = sv
        for shift in tl.static_range(LOG):
            partner = tl.maximum(lane - (1 << shift), 0)
            previous_target = tl.gather(targets.to(tl.float32), partner, axis=0).to(
                tl.int32
            )
            previous_sum = tl.gather(segment_sums, partner, axis=0)
            segment_sums = segment_sums + tl.where(
                (lane >= (1 << shift)) & (targets == previous_target),
                previous_sum,
                0.0,
            )
        tl.store(prefix_ptr + row * B + lane, segment_sums)


@triton.jit
def _scatter_add_sort_out_kernel(
    inp_ptr,
    keys_ptr,
    prefix_ptr,
    out_ptr,
    rows,
    out_cols: tl.constexpr,
    src_cols: tl.constexpr,
    B: tl.constexpr,
    LOG: tl.constexpr,
):
    """Per row: binary-search each destination's run in the sorted keys and
    emit ``inp + segment_sum[end-1]`` contiguously; absent rows add zero.

    The row is loaded once and searched on-chip (a data-dependent *global*
    load costs ~25x the matching ``tl.gather`` on this backend).
    """
    pid = tl.program_id(0)
    npid = tl.num_programs(0)
    dst = tl.arange(0, B)
    t1 = dst.to(tl.float32) * B
    for row in range(pid, rows, npid):
        base = row * B
        keys = tl.load(keys_ptr + base + dst)
        prefix = tl.load(prefix_ptr + base + dst)
        lo = tl.zeros([B], tl.int32)
        hi = tl.full([B], B, tl.int32)
        for _ in tl.static_range(LOG + 1):
            mid = tl.minimum((lo + hi) >> 1, B - 1)
            go = (tl.gather(keys, mid, axis=0) < t1) & (lo < hi)
            lo = tl.where(go, mid + 1, lo)
            hi = tl.where(go, hi, tl.minimum(mid, hi))
        # The run end for ``dst`` is the run start of ``dst + 1``; the last
        # destination is followed by exactly ``src_cols`` real keys.
        nxt = tl.gather(lo.to(tl.float32), tl.minimum(dst + 1, B - 1), axis=0).to(
            tl.int32
        )
        end = tl.where(dst == out_cols - 1, src_cols, nxt)
        after = tl.gather(prefix, tl.maximum(tl.minimum(end - 1, B - 1), 0), axis=0)
        delta = tl.where(end > lo, after, 0.0)
        live = dst < out_cols
        init = tl.load(inp_ptr + row * out_cols + dst, mask=live, other=0.0).to(
            tl.float32
        )
        tl.store(
            out_ptr + row * out_cols + dst,
            (init + delta).to(out_ptr.dtype.element_ty),
            mask=live,
        )


# --------------------------------------------------------------------------- #
# last-axis atomic kernel (fp32 accumulation)
# --------------------------------------------------------------------------- #
@triton.jit(
    do_not_specialize=["rows", "nblocks", "out_cols", "src_cols", "src_row_stride"]
)
def _scatter_add_atomic_kernel(
    src_ptr,
    idx_ptr,
    out_ptr,
    rows,
    nblocks,
    out_cols,
    src_cols,
    src_row_stride,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    npid = tl.num_programs(0)
    total = rows * nblocks
    for t in range(pid, total, npid):
        row = t // nblocks
        blk = t - row * nblocks
        c = blk * BLOCK + tl.arange(0, BLOCK)
        mask = c < src_cols
        idx_base = row * src_cols
        src_base = row * src_row_stride
        out_base = row * out_cols
        idx = tl.load(idx_ptr + idx_base + c, mask=mask, other=0).to(tl.int32)
        val = tl.load(src_ptr + src_base + c, mask=mask, other=0).to(
            out_ptr.dtype.element_ty
        )
        tl.atomic_add(out_ptr + (out_base + idx), val, mask=mask, sem="relaxed")


# --------------------------------------------------------------------------- #
# generic N-d kernel (any dim / strides; int64 addressing)
# --------------------------------------------------------------------------- #
@triton.jit(do_not_specialize=["n", "odim"] + _D_ARGS + _SS_ARGS + _IS_ARGS + _OS_ARGS)
def _scatter_add_nd_kernel(
    src_ptr,
    index_ptr,
    out_ptr,
    n,
    odim,
    d0,
    d1,
    d2,
    d3,
    d4,
    d5,
    d6,
    d7,
    ss0,
    ss1,
    ss2,
    ss3,
    ss4,
    ss5,
    ss6,
    ss7,
    is0,
    is1,
    is2,
    is3,
    is4,
    is5,
    is6,
    is7,
    os0,
    os1,
    os2,
    os3,
    os4,
    os5,
    os6,
    os7,
    BLOCK: tl.constexpr,
):
    """Scatter-add over the ``index``/``src`` element space.

    ``ss``/``is`` are the strides of ``src``/``index``; ``os`` are the
    (contiguous) strides of the output with the entry for ``dim`` forced to 0,
    so the ``dim`` coordinate is contributed only through ``idx * odim``.
    """
    pid = tl.program_id(0)
    step = tl.num_programs(0)
    for blk in range(pid, tl.cdiv(n, BLOCK), step):
        off = blk * BLOCK + tl.arange(0, BLOCK)
        mask = off < n
        cur = off
        src_off = tl.zeros([BLOCK], dtype=tl.int64)
        idx_off = tl.zeros([BLOCK], dtype=tl.int64)
        out_off = tl.zeros([BLOCK], dtype=tl.int64)

        md = cur % d7
        src_off += md * ss7
        idx_off += md * is7
        out_off += md * os7
        cur = cur // d7

        md = cur % d6
        src_off += md * ss6
        idx_off += md * is6
        out_off += md * os6
        cur = cur // d6

        md = cur % d5
        src_off += md * ss5
        idx_off += md * is5
        out_off += md * os5
        cur = cur // d5

        md = cur % d4
        src_off += md * ss4
        idx_off += md * is4
        out_off += md * os4
        cur = cur // d4

        md = cur % d3
        src_off += md * ss3
        idx_off += md * is3
        out_off += md * os3
        cur = cur // d3

        md = cur % d2
        src_off += md * ss2
        idx_off += md * is2
        out_off += md * os2
        cur = cur // d2

        md = cur % d1
        src_off += md * ss1
        idx_off += md * is1
        out_off += md * os1
        cur = cur // d1

        md = cur % d0
        src_off += md * ss0
        idx_off += md * is0
        out_off += md * os0

        idx = tl.load(index_ptr + idx_off, mask=mask, other=0).to(tl.int64)
        val = tl.load(src_ptr + src_off, mask=mask, other=0).to(
            out_ptr.dtype.element_ty
        )
        out_off += idx * odim
        tl.atomic_add(out_ptr + out_off, val, mask=mask, sem="relaxed")


# --------------------------------------------------------------------------- #
# host side
# --------------------------------------------------------------------------- #
def _contig_strides(shape):
    strides = [0] * len(shape)
    acc = 1
    for i in range(len(shape) - 1, -1, -1):
        strides[i] = acc
        acc *= shape[i]
    return strides


def _is_lastdim_fastpath(inp, dim, index, src):
    return (
        inp.dim() == 2
        and dim == 1
        and inp.is_contiguous()
        and index.is_contiguous()
        and index.shape[0] == inp.shape[0]
        and src.dim() == 2
        and src.stride(1) == 1
        and src.shape[0] >= index.shape[0]
        and src.shape[1] >= index.shape[1]
        and index.numel() <= _INT32_MAX
    )


def _run_lastdim(inp, index, src, out):
    rows = index.shape[0]
    src_cols = index.shape[1]
    out_cols = inp.shape[1]
    src_row_stride = src.stride(0)

    if out_cols == 0:
        _copy(inp, out)
        return out

    grid_rows = min(rows, _MAX_GRID_X)

    # Destination-owned: cheapest while both widths are small.
    if out_cols <= _DENSE_MAX_COLS and src_cols <= _DENSE_MAX_SRC:
        block = min(128, max(32, triton.next_power_of_2(out_cols)))
        # ``EVEN`` requires an unmasked source loop and an exact destination
        # grid; both follow from the two divisibility checks.
        even = src_cols % _DENSE_CHUNK == 0 and out_cols % block == 0
        col_blocks = triton.cdiv(out_cols, block)
        # Flat program space: the launcher rejects any grid whose *product*
        # exceeds coreDim (rows * blocks can easily exceed 65535).
        grid = (min(rows * col_blocks, _MAX_GRID_X),)
        _scatter_add_owner_kernel[grid](
            inp,
            index,
            src,
            out,
            rows,
            col_blocks,
            out_cols,
            src_cols,
            src_row_stride,
            BLOCK=block,
            CHUNK=_DENSE_CHUNK,
            EVEN=even,
        )
        return out

    # Sorted-segment: B covers both sides, so junk keys sort last and
    # ``(B-1)*B + B-1 == B*B - 1 < 2**24`` keeps the keys exact in fp32.
    B = triton.next_power_of_2(max(out_cols, src_cols))
    if B <= _SORT_MAX_B:
        LOG = B.bit_length() - 1
        keys = torch.empty((rows, B), dtype=torch.float32, device=inp.device)
        prefix = torch.empty((rows, B), dtype=torch.float32, device=inp.device)
        _scatter_add_sort_key_kernel[(grid_rows,)](
            src,
            index,
            keys,
            prefix,
            rows,
            out_cols,
            src_cols,
            src_row_stride,
            B=B,
            LOG=LOG,
        )
        _scatter_add_sort_out_kernel[(grid_rows,)](
            inp,
            keys,
            prefix,
            out,
            rows,
            out_cols,
            src_cols,
            B=B,
            LOG=LOG,
        )
        return out

    # Atomic fallback for very wide rows.  fp32 accumulates in an fp32 buffer
    # and rounds once on store; fp32 inputs scatter straight into ``out``.
    if inp.dtype in (torch.float16, torch.bfloat16):
        buf = torch.empty(inp.shape, dtype=torch.float32, device=inp.device)
        _copy(inp, buf)
        nblocks = triton.cdiv(src_cols, _ATOMIC_BLOCK)
        _scatter_add_atomic_kernel[(min(rows * nblocks, _MAX_GRID_X),)](
            src,
            index,
            buf,
            rows,
            nblocks,
            out_cols,
            src_cols,
            src_row_stride,
            BLOCK=_ATOMIC_BLOCK,
        )
        _copy(buf, out)
        return out
    _copy(inp, out)
    nblocks = triton.cdiv(src_cols, _ATOMIC_BLOCK)
    _scatter_add_atomic_kernel[(min(rows * nblocks, _MAX_GRID_X),)](
        src,
        index,
        out,
        rows,
        nblocks,
        out_cols,
        src_cols,
        src_row_stride,
        BLOCK=_ATOMIC_BLOCK,
    )
    return out


def _run_generic(inp, dim, index, src, out):
    n = index.numel()
    dtype = inp.dtype
    acc_f32 = dtype in (torch.float16, torch.bfloat16)
    buf = (
        torch.empty(inp.shape, dtype=torch.float32, device=inp.device)
        if acc_f32
        else out
    )
    _copy(inp, buf)

    # ``src`` follows ``index``'s extent; extra trailing entries are never read.
    src_view = (
        src.as_strided(index.shape, src.stride()) if src.shape != index.shape else src
    )
    pad = _MAXR - index.dim()
    idx_shape = [1] * pad + list(index.shape)
    src_strides = [0] * pad + list(src_view.stride())
    idx_strides = [0] * pad + list(index.stride())
    out_strides = _contig_strides(inp.shape)
    odim = out_strides[dim]
    out_strides[dim] = 0
    z = [0] * pad
    out_slots = z + out_strides

    grid = (min(triton.cdiv(n, 512), _MAX_GRID_X),)
    _scatter_add_nd_kernel[grid](
        src_view,
        index,
        buf,
        n,
        odim,
        idx_shape[0],
        idx_shape[1],
        idx_shape[2],
        idx_shape[3],
        idx_shape[4],
        idx_shape[5],
        idx_shape[6],
        idx_shape[7],
        src_strides[0],
        src_strides[1],
        src_strides[2],
        src_strides[3],
        src_strides[4],
        src_strides[5],
        src_strides[6],
        src_strides[7],
        idx_strides[0],
        idx_strides[1],
        idx_strides[2],
        idx_strides[3],
        idx_strides[4],
        idx_strides[5],
        idx_strides[6],
        idx_strides[7],
        out_slots[0],
        out_slots[1],
        out_slots[2],
        out_slots[3],
        out_slots[4],
        out_slots[5],
        out_slots[6],
        out_slots[7],
        BLOCK=512,
    )
    if acc_f32:
        _copy(buf, out)
    return out


def _run(inp, dim, index, src, out):
    d = dim % inp.ndim
    if index.numel() == 0:
        _copy(inp, out)
        return out
    if _is_lastdim_fastpath(inp, d, index, src):
        return _run_lastdim(inp, index, src, out)
    return _run_generic(inp, d, index, src, out)


def scatter_add(inp, dim, index, src):
    logger.debug("GEMS_ASCEND SCATTER_ADD")
    out = torch.empty(inp.shape, dtype=inp.dtype, device=inp.device)
    return _run(inp, dim, index, src, out)


def scatter_add_(x, dim, index, src):
    logger.debug("GEMS_ASCEND SCATTER_ADD_")
    if x.is_contiguous():
        return _run(x, dim, index, src, x)
    out = torch.empty(x.shape, dtype=x.dtype, device=x.device)
    res = _run(x, dim, index, src, out)
    x.copy_(res)
    return x
